package com.company.skillplatform.compatibility.application;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.company.skillplatform.compatibility.domain.*;import com.company.skillplatform.compatibility.infrastructure.entity.*;import com.company.skillplatform.compatibility.infrastructure.repository.*;import com.company.skillplatform.skill.application.SkillService;import com.company.skillplatform.skill.infrastructure.entity.SkillEntity;import com.company.skillplatform.user.infrastructure.entity.IamUserEntity;import com.company.skillplatform.version.domain.*;import com.company.skillplatform.version.infrastructure.entity.SkillVersionEntity;import com.company.skillplatform.version.infrastructure.repository.SkillVersionRepository;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.test.util.ReflectionTestUtils;
class CompatibilityServiceTest{SkillVersionCompatibilityRepository compat=mock(SkillVersionCompatibilityRepository.class);PlatformRepository platforms=mock(PlatformRepository.class);PlatformAgentRepository agents=mock(PlatformAgentRepository.class);PlatformAdapterRepository adapters=mock(PlatformAdapterRepository.class);SkillVersionRepository versions=mock(SkillVersionRepository.class);SkillService skills=mock(SkillService.class);CompatibilityService service;SkillVersionEntity version;PlatformEntity platform;@Test void adapterViewIsStructured(){assertThat(new CompatibilityService.AdapterView("1","bean").implementationKey()).isEqualTo("bean");}
 @BeforeEach void setup(){service=new CompatibilityService(compat,platforms,agents,adapters,versions,skills);version=new SkillVersionEntity(mock(SkillEntity.class),null,ChangeType.INITIAL,mock(IamUserEntity.class));ReflectionTestUtils.setField(version,"id",10L);platform=mock(PlatformEntity.class);when(platform.getId()).thenReturn(2L);when(platform.getPlatformKey()).thenReturn("OPENCODE");when(platform.getPlatformName()).thenReturn("OpenCode");when(platform.getStatus()).thenReturn("ACTIVE");when(skills.version(10L)).thenReturn(version);when(platforms.findByPlatformKey("OPENCODE")).thenReturn(Optional.of(platform));when(versions.incrementVersion(10L,0)).thenReturn(1);}
 @Test void replacesListsValidatesAndListsPlatforms(){var command=new CompatibilityService.CompatibilityCommand("OPENCODE",null,OsType.WINDOWS,true,CompatibilityStatus.TRANSFORM_REQUIRED,null,null,"overlays/opencode.yaml");assertThat(service.replace(10L,0,List.of(command),1L)).hasSize(1);SkillVersionCompatibilityEntity entity=new SkillVersionCompatibilityEntity(version,platform,null,OsType.WINDOWS,true,CompatibilityStatus.TRANSFORM_REQUIRED,null,null,"overlays/opencode.yaml");when(compat.findByVersionId(10L)).thenReturn(List.of(entity));assertThat(service.list(10L)).hasSize(1);assertThat(service.validate(10L,1L).get(0).validatedStatus()).isEqualTo(CompatibilityStatus.COMPATIBLE);when(platforms.findAll()).thenReturn(List.of(platform));when(adapters.findByPlatformId(2L)).thenReturn(List.of());assertThat(service.platforms()).extracting("platformKey").containsExactly("OPENCODE");}
 @Test void rejectsStaleUpdate(){when(versions.incrementVersion(10L,3)).thenReturn(0);assertThatThrownBy(()->service.replace(10L,3,List.of(),1L)).isInstanceOf(RuntimeException.class);}
}
